{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/team-grid.json
    The people of a team: portrait cards, a minimal grid of small portraits, detailed cards with skills, rows beside a picture, or a directory of two columns. Axes: layout (cards, minimal, detailed, list, directory), cols, tone, density.
    Props (p): id, title, lead, members, depts, layout, cols, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_members = ($p['members'] ?? null)}
{var $v_depts = ($p['depts'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_cols = ($p['cols'] ?? '1-4')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_11}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '3/4']])|noescape}
{/capture}
{capture $c_12}
  {capture $c_10}
    {foreach ui_l($v_members) as $v_m}
      {if ui_t(ui_eq($v_layout, 'minimal'))}
        {capture $c_3}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_m, ['name']), 'ratio' => '1/1', 'className' => ui_cnv([ui_cnv(['size-16', 'shrink-0'])])]])|noescape}
          {capture $c_1}
            {=ui_text(ui_get($v_m, ['name']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
          {capture $c_2}
            {=ui_text(ui_get($v_m, ['role']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Class' => 'text-center', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_3])|noescape}
      {elseif ui_t(ui_eq($v_layout, 'cards'))}
        {capture $c_9}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_m, ['name']), 'ratio' => '1/1']])|noescape}
          {capture $c_8}
            {capture $c_6}
              {capture $c_4}
                {=ui_text(ui_get($v_m, ['name']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_4])|noescape}
              {capture $c_5}
                {=ui_text(ui_get($v_m, ['role']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
            {/capture}
            {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_6])|noescape}
            {capture $c_7}
              {=ui_text(ui_get($v_m, ['bio']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_7])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_8])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_9])|noescape}
      {else}
        {=ui_include('blocks/member-row.latte', ['p' => ['member' => $v_m, 'depts' => $v_depts, 'layout' => $v_layout]])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'minimal')) ? 'grid grid-cols-2 gap-8 md:grid-cols-4' : (ui_t(ui_eq($v_layout, 'directory')) ? 'grid grid-cols-1 gap-4 md:grid-cols-2' : (ui_t(ui_eq($v_layout, 'list')) ? 'flex flex-col gap-4' : (ui_t(ui_eq($v_cols, '1-3')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-4'))))), 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'layout' => (ui_t(ui_eq($v_layout, 'list')) ? 'split' : 'stack'), 'media' => ['show' => ui_eq($v_layout, 'list'), 'side' => 'start', 'align' => 'start'], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_11], 'children' => $c_12])|noescape}
